<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/business_helpers.php';require_login();$error='';
$selected=(int)($_GET['car_id']??0);$cars=$conn->query("SELECT c.id,c.car_name,c.plate_number,c.asking_price FROM cars c WHERE c.status='IN_STOCK' AND NOT EXISTS(SELECT 1 FROM reservations r WHERE r.car_id=c.id AND r.status='ACTIVE' AND (r.expiry_date IS NULL OR r.expiry_date>=CURDATE())) ORDER BY c.car_name");
if($_SERVER['REQUEST_METHOD']==='POST'){$carId=(int)($_POST['car_id']??0);$name=trim($_POST['customer_name']??'');$phone=trim($_POST['customer_phone']??'');$deposit=(float)($_POST['deposit_amount']??0);$date=$_POST['reserve_date']??'';$expiry=$_POST['expiry_date']?:null;$notes=trim($_POST['notes']??'');$uid=(int)$_SESSION['user_id'];if(!$carId||$name===''||$date===''){$error='Car, customer name and reservation date are required.';}else{$cid=find_or_create_customer($conn,$name,$phone,'',$uid);$st=$conn->prepare('INSERT INTO reservations(car_id,customer_id,customer_name,customer_phone,deposit_amount,reserve_date,expiry_date,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$st->bind_param('iissdsssi',$carId,$cid,$name,$phone,$deposit,$date,$expiry,$notes,$uid);if($st->execute()){$rid=(int)$st->insert_id;car_sales_audit($conn,'CREATE','reservation',$rid,'Created reservation for '.$name.'.',null,['car_id'=>$carId,'customer_name'=>$name,'deposit_amount'=>$deposit,'reserve_date'=>$date,'expiry_date'=>$expiry]);set_flash('success','Reservation recorded successfully.');redirect_to('backend/reservations/index.php');}else{$error='Could not record reservation.';}}}
$page_title='New Reservation';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><h1 class="page-title">New Reservation</h1><div class="card form-card"><?php if($error):?><div class="flash-message error" style="position:static"><?=e($error)?></div><?php endif;?><form method="post"><div class="form-group"><label>Car *</label><select name="car_id" required><option value="">Select car</option><?php while($c=$cars->fetch_assoc()):?><option value="<?=$c['id']?>" <?=$selected===(int)$c['id']?'selected':''?>><?=e($c['car_name'].' / '.car_sales_plate_label($c['plate_number']))?><?= $c['asking_price']?' - '.money($c['asking_price']):''?></option><?php endwhile;?></select></div><div class="form-row"><div class="form-group"><label>Customer Name *</label><input name="customer_name" required></div><div class="form-group"><label>Customer Phone</label><input name="customer_phone"></div></div><div class="form-row"><div class="form-group"><label>Deposit Amount</label><input type="number" step="0.01" min="0" name="deposit_amount" value="0"></div><div class="form-group"><label>Reservation Date *</label><input type="date" name="reserve_date" value="<?=date('Y-m-d')?>" required></div></div><div class="form-group"><label>Expiry Date</label><input type="date" name="expiry_date"></div><div class="form-group"><label>Notes / Conditions</label><textarea name="notes" rows="3"></textarea></div><button class="btn btn-green">Save Reservation</button><a class="btn btn-dark" href="index.php">Cancel</a></form></div></div><?php include __DIR__.'/../includes/footer.php';?>
